// 准备浏览器访问参数
const articleUrl = $json.article_url;

if (!articleUrl) {
    throw new Error('Missing article_url parameter');
}

// 验证是否为微信文章链接
if (!articleUrl.includes('mp.weixin.qq.com')) {
    throw new Error('Invalid WeChat article URL');
}

return {
    article_url: articleUrl,
    timestamp: new Date().toISOString()
};

// 等待页面加载完成
const page = this.getPage();

// 等待关键元素加载
await page.waitForSelector('body', { timeout: 15000 });

// 滚动页面以触发懒加载内容
await page.evaluate(() => {
    window.scrollTo(0, document.body.scrollHeight / 2);
});

// 等待一下让内容加载
await page.waitForTimeout(3000);

// 再滚动到底部
await page.evaluate(() => {
    window.scrollTo(0, document.body.scrollHeight);
});

// 等待最终内容加载
await page.waitForTimeout(2000);

return { status: 'page_loaded' };

// 提取文章标题和内容
const page = this.getPage();

// 获取页面HTML
const html = await page.content();

// 使用cheerio解析
const cheerio = require('cheerio');
const $ = cheerio.load(html);

// 提取标题 - 多种选择器
let title = '';
const titleSelectors = [
    '#activity-name',
    '.rich_media_title',
    'h1.title', 
    'h1',
    '.weui-msg__title',
    '[data-role="title"]',
    '.rich_media_area_primary .rich_media_title'
];

for (const selector of titleSelectors) {
    const element = $(selector);
    if (element.length > 0 && element.text().trim()) {
        title = element.text().trim();
        break;
    }
}

// 提取正文内容 - 多种选择器
let content = '';
const contentSelectors = [
    '#js_content',
    '.rich_media_content',
    '.article-content', 
    '.content',
    '[data-role="content"]',
    '.weui-article__bd',
    'div.rich_media_area_primary .rich_media_content'
];

for (const selector of contentSelectors) {
    const element = $(selector);
    if (element.length > 0) {
        // 清理不需要的元素
        element.find('script, style, .rich_media_tool, .profile_container, .reward_area').remove();
        content = element.text().trim();
        if (content.length > 200) { // 确保获取到足够内容
            break;
        }
    }
}

// 如果还没有内容，尝试更通用的方法
if (!content || content.length < 100) {
    // 移除不需要的元素
    $('script, style, nav, footer, header, .ad, .advertisement, .rich_media_tool').remove();
    // 尝试获取主要内容区域
    const mainContent = $('.rich_media_area_primary').text().trim() || $('body').text().trim();
    if (mainContent && mainContent.length > content.length) {
        content = mainContent;
    }
}

// 清理内容
if (content) {
    content = content
        .replace(/\s+/g, ' ')
        .replace(/微信号.*?功能介绍/g, '')
        .replace(/长按二维码识别.*?$/g, '')
        .replace(/点击上方.*?关注/g, '')
        .replace(/阅读原文.*?$/g, '')
        .replace(/\d+人点赞/g, '')
        .replace(/分享.*?朋友圈/g, '')
        .replace(/更多精彩内容.*?$/g, '')
        .trim();
}

const articleUrl = $input.first().json.article_url || '';

return {
    title: title || '未能提取标题',
    content: content || '未能提取正文内容',
    url: articleUrl,
    extracted_at: new Date().toISOString(),
    extraction_method: 'browser_automation',
    debug_info: {
        html_length: html.length,
        title_found: !!title,
        content_length: content.length,
        page_title: await page.title()
    }
};

// 处理DeepSeek API响应
const aiResponse = $input.first().json;
let summary = '';

try {
    if (aiResponse.choices && aiResponse.choices.length > 0) {
        summary = aiResponse.choices[0].message.content.trim();
    } else {
        summary = '总结生成失败';
    }
} catch (error) {
    summary = '总结解析错误: ' + error.message;
}

// 合并所有数据
const previousData = $input.first().json;
return {
    ...previousData,
    summary: summary,
    processed_at: new Date().toISOString(),
    processing_status: 'completed'
};
